from database.staging_tables import (
    staging_auctions,
    staging_bid_events,
    staging_lot_bid_histories,
    staging_lot_details,
    staging_lot_summaries,
)

from macbid_scraper.items import (
    AuctionRecordItem,
    LotBidHistoryItem,
    LotDetailItem,
    LotSummaryItem,
    SingleBidItem,
)

# These columns are generated by the pipeline rather than carried by
# API-derived Items.
PIPELINE_ONLY_FIELDS = {
    "collection_run_id",
}

ITEM_TABLE_PAIRS = (
    (
        AuctionRecordItem,
        staging_auctions,
    ),
    (
        LotSummaryItem,
        staging_lot_summaries,
    ),
    (
        LotDetailItem,
        staging_lot_details,
    ),
    (
        LotBidHistoryItem,
        staging_lot_bid_histories,
    ),
    (
        SingleBidItem,
        staging_bid_events,
    ),
)

def test_item_fields_match_table_columns():
    for item_class, table in ITEM_TABLE_PAIRS:
        # Generate set containing all fields from the item
        item_fields = set(
            item_class.fields.keys()
        )
        # Generate set containing all columns from the table
        table_columns = set(
            table.c.keys()
        )

        # Expected item fields should have the same values as 
        # the table columns, without the pipeline-only fields
        expected_item_fields = (
            table_columns 
            - PIPELINE_ONLY_FIELDS
        )

        # Find values that are in the item but not in the table
        missing_from_table = (
            item_fields
            - table_columns
        )

        # Find values that are in the expected item fields but not
        # the actual item fields
        missing_from_item = (
            expected_item_fields
            - item_fields
        )

        assert not missing_from_table, (
            f"{item_class.__name__} contains "
            "fields missing from "
            f"{table.name}: "
            f"{sorted(missing_from_table)}"
        )

        assert not missing_from_item, (
            f"{table.name} contains fields "
            "missing from "
            f"{item_class.__name__}: "
            f"{sorted(missing_from_item)}"
        )